/**
 * @param {Object|Array} obj
 * @return {Object}
 */
var invertObject = function(obj) {
    const result = {};

    // Object.keys works for both objects and arrays; for arrays it yields
    // the string indices "0", "1", ...
    for (const key of Object.keys(obj)) {
        const val = obj[key];   // guaranteed to be a string

        if (Object.prototype.hasOwnProperty.call(result, val)) {
            if (Array.isArray(result[val])) {
                result[val].push(key);
            } else {
                result[val] = [result[val], key];
            }
        } else {
            result[val] = key;
        }
    }

    return result;
};
